import 'package:flutter/material.dart';class ProductReviewsWidget extends StatelessWidget {  final List<Map<String, dynamic>> reviews = [    {      "name": "Mark Williams",      "avatar": "https://via.placeholder.com/50", // Sample avatar      "rating": 5,      "title": "Excellent Product, I Love It 😍",      "review":      "It is a long established fact that a reader will be distracted by the readable content of a page when looking at its layout.",      "date": "June 05, 2023"    },  ];  ProductReviewsWidget({super.key});  @override  Widget build(BuildContext context) {    return ListView(      physics: NeverScrollableScrollPhysics(),      children: [        // Customer Reviews Section        Text(          "Customer Reviews",          style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),        ),        SizedBox(height: 16),        // Review List        Column(          children: reviews.map((review) => _buildReviewCard(review)).toList(),        ),        SizedBox(height: 20),        // Add Review Section        Text(          "Add your Review",          style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),        ),        SizedBox(height: 10),        // Star Rating Input        Text("Your Rating"),        SizedBox(height: 8),        _buildStarRatingInput(),        SizedBox(height: 16),        // Name Input        _buildTextField("Name", "Enter Your Name"),        SizedBox(height: 16),        // Email Input        _buildTextField("Email Address", "Enter Your Email"),        SizedBox(height: 16),        // Review Input        _buildTextField("Your Review", "Enter Your Review", maxLines: 4),        SizedBox(height: 20),       // Submit Button        Padding(          padding: const EdgeInsets.only(bottom: 50),          child: ElevatedButton(            style: ElevatedButton.styleFrom(              backgroundColor: Colors.black,              padding: EdgeInsets.symmetric(vertical: 12),            ),            onPressed: () {              // Handle submit action            },            child: Text(              "Submit",              style: TextStyle(color: Colors.white, fontSize: 16),            ),          ),        ),      ],    );  }  // Function to build individual review cards  Widget _buildReviewCard(Map<String, dynamic> review) {    return Column(      children: [        Row(          crossAxisAlignment: CrossAxisAlignment.start,          children: [            // User Avatar            CircleAvatar(              // backgroundImage: NetworkImage(review["avatar"]),              radius: 24,            ),            SizedBox(width: 10),            // Review Details            Expanded(              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  Text(                    review["name"],                    style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),                  ),                  SizedBox(height: 4),                  // Star Rating                  Row(                    children: List.generate(                      review["rating"],                          (index) => Icon(Icons.star, color: Colors.orange, size: 18),                    ),                  ),                  SizedBox(height: 4),                  // Review Title                  Text(                    review["title"],                    style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold),                  ),                  SizedBox(height: 4),                  // Review Text                  Text(                    review["review"],                    style: TextStyle(fontSize: 14, color: Colors.black87),                  ),                  SizedBox(height: 4),                  // Review Date                  Text(                    "Review by Krist | Posted on ${review["date"]}",                    style: TextStyle(fontSize: 12, color: Colors.grey),                  ),                ],              ),            ),          ],        ),        Divider(),      ],    );  }  // Star Rating Input  Widget _buildStarRatingInput() {    return Row(      children: List.generate(        5,            (index) => Icon(Icons.star_border, color: Colors.grey, size: 24),      ),    );  }  // Text Input Field  Widget _buildTextField(String label, String hint, {int maxLines = 1}) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Text(label, style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold)),        SizedBox(height: 6),        TextField(          maxLines: maxLines,          decoration: InputDecoration(            hintText: hint,            border: OutlineInputBorder(),            contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 10),          ),        ),      ],    );  }}